#include "control_home/rtcp_device.hpp"
#include <cstdio>
#include <string>

namespace control_home{using namespace control;
Evidence RtcpDevice::evidence(const char*id,const char*claim)const{Evidence e;e.evidence_id=Id(id);e.kind=EvidenceKind::PROJECT_DESIGN;e.reference=Text::literal("A-REMOTE-011 RTCP/1 Phase 3 candidate");e.verified_claims.push(Text(claim));e.version=Value<Text>::of(Text::literal("1"));return e;}
bool RtcpDevice::install(Core&c,ingress::Boundary&b,const Id&d,const Id&t,const Id&bid,U64 now){core_=&c;boundary_=&b;binding_=bid;CommonDevice device;device.device_id=d;device.display_name=Text::literal("TUNER//01");device.device_class=CommonDevice::Class::AUDIO_PLAYER;Target target;target.device_id=d;target.target_id=t;target.display_name=Text::literal("TUNER//01 audio");Binding binding;binding.device_id=d;binding.target_id=t;binding.binding_id=bid;binding.authorization=Authorization::AUTHORIZED;binding.reachability=Reachability::UNREACHABLE;binding.adapter_version=version();binding.model_versions.push(Version{1,1,0,{}});binding.mapping_evidence.push(evidence("a011.binding","authenticated RTCP/1 mapping candidate"));if(c.register_device(device,now).present||c.register_target(target,now).present||c.register_binding(binding,*this,now).present||!b.attach(bid,now))return false;auto op=MockAdapter::operation(bid,"volume.set",Feedback::CORRELATED_RESULT);op.availability=Availability::OFFLINE;op.evidence.clear();op.evidence.push(evidence("a011.volume.set","normalized exact-grid volume.set mapping"));op.execution_evidence.value.mapping_reference=Text::literal("RTCP/1 application type 7/8");if(!b.capability(std::move(op),now))return false;for(auto name:{"volume.level","playback.state"}){auto f=MockAdapter::readable(bid,name);f.availability=Availability::OFFLINE;f.freshness=freshness_policy();f.evidence.clear();f.evidence.push(evidence(name,"fresh verified-sequence RTCP snapshot"));if(!b.capability(std::move(f),now))return false;}return true;}
void RtcpDevice::availability(Availability value,U64 now){auto*b=core_->binding(binding_);auto*t=core_->target(b->device_id,b->target_id);for(auto cap:t->capabilities){cap.availability=value;boundary_->capability(std::move(cap),now);}}
void RtcpDevice::dispatch(const Dispatch&d,AdapterSink&sink){AdapterEvidence e;e.request_id=d.request.request_id;e.binding_id=d.attempt.binding_id;e.attempt_index=d.attempt.attempt_index;e.mapping_revision=d.attempt.mapping_revision;e.session_generation=d.attempt.session_generation;e.evidence=evidence("a011.dispatch","one RTCP command correlated to one CCM request");LockKey key;key.device_id=d.request.device_id;key.target_id=d.request.target_id;e.covered_keys.push(key);e.progress=Progress{1,0,0,false};if(d.request.operation_id.view()!="volume.set"||!d.mapped_numeric.present||!client_.set_volume(d.request.admission_ticket.serial,std::uint32_t(d.mapped_numeric.value.n),std::uint32_t(d.mapped_numeric.value.d))){e.signal=AdapterEvidence::Signal::FAIL;e.delivery=Delivery::NOT_SENT;e.closed=true;e.failure=error(ErrorCode::UNAVAILABLE,"RTCP_NOT_SENT",RejectionOrigin::TARGET);sink.publish(e);return;}++dispatches_;e.delivery=Delivery::SENT;e.progress.value.emitted=1;sink.publish(e);pending_=e;}
bool RtcpDevice::poll(U64 now){auto event=client_.poll(now);if(event==rtcp_client::Client::Event::none)return true;if(event==rtcp_client::Client::Event::connected){if(!boundary_->reconnect(now)||!boundary_->reachability(Reachability::REACHABLE,now))return false;availability(Availability::UNKNOWN,now);return true;}if(event==rtcp_client::Client::Event::disconnected){availability(Availability::OFFLINE,now);return boundary_->reachability(Reachability::UNREACHABLE,now);}if(event==rtcp_client::Client::Event::capabilities){availability(Availability::READY,now);return true;}if(event==rtcp_client::Client::Event::snapshot){const auto&s=client_.snapshot();auto publish=[&](const char*field,Scalar value,bool media){StateObservation o;o.observation_id=Id((std::string("rtcp.observation.")+std::to_string(++observations_)).c_str());auto*b=core_->binding(binding_);auto*t=core_->target(b->device_id,b->target_id);auto*d=core_->device(b->device_id);o.device_id=d->device_id;o.target_id=t->target_id;o.field_id=Text(field);o.value=Value<Scalar>::of(value);o.confidence=Confidence::REPORTED;o.binding_id=binding_;o.device_association_generation=d->association_generation;o.association_generation=t->association_generation;o.mapping_revision=b->mapping_revision;o.session_generation=b->session_generation;o.receipt_time={core_->storage().clock_epoch,now};o.age_at_receipt_ms=0;o.clock_quality=ClockQuality::BOUNDED;o.origin=Origin::LIVE;o.acquisition_order=s.sequence;o.source_sequence=Sequence{Id("rtcp.tuner.sequence"),s.sequence};o.freshness=freshness_policy();if(media)o.media_context_generation=t->media_context_generation;ProvenanceHop h;h.actor_id=identity();h.evidence_id=Id("a011.snapshot");o.provenance.push(h);return boundary_->observe(std::move(o),now);};Scalar volume=Scalar::level(volume_rational(s.volume));Scalar playback;playback.kind=ScalarKind::PLAYBACK;playback.playback=static_cast<Playback>(s.playback);const bool volume_ok=publish("volume.level",volume,false);const bool playback_ok=publish("playback.state",playback,true);return volume_ok&&playback_ok;}if(event==rtcp_client::Client::Event::result&&pending_.present){auto e=pending_.value;const auto&r=client_.result();e.evidence=evidence("a011.result","authenticated correlated TUNER result");e.closed=true;if(r.accepted){e.signal=AdapterEvidence::Signal::COMPLETE;e.delivery=Delivery::ACKNOWLEDGED;e.progress.value.confirmed=1;}else{e.signal=AdapterEvidence::Signal::REFUSE;e.delivery=Delivery::ACKNOWLEDGED;e.failure=error(ErrorCode::INVALID_ARGUMENT,"TUNER_REJECTED",RejectionOrigin::TARGET);}pending_={};return boundary_->report(std::move(e),now);}return true;}
}
